#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic)
# campaign_split_v6.sh — daytime split-CPU campaign (host_perf_mode.sh split):
#   application + nsys on the P-cores, observer on E-cores 12-17, desktop on 18-19.
#   1. Isaac ROS ros2_benchmark sweep, 13 benches x (warmup + 3 modes x 3 reps)
#   2. Autoware logging_simulator, 3 modes x 3 reps, rate 0.5
# Preconditions checked: lo multicast ON (Cyclone DDS single-host config,
# 2026-09-05: it was off in every earlier campaign), split cpuset online.
set -u
LOG=$HOME/fish_traces/campaign_split_v6_full.log
exec > >(tee -a "$LOG") 2>&1
stamp() { echo "[campaign $(date '+%F %T')] $*"; }
export FISH_APP_CPUS=${FISH_APP_CPUS:-0,2,4,6,8,10}
export FISH_OBS_CPUS=${FISH_OBS_CPUS:-12-17}
export FISH_EVENT_COUNT=0
cd "$(dirname "$0")/.."

stamp "start — app=$FISH_APP_CPUS obs=$FISH_OBS_CPUS"
ip -o link show lo | grep -q MULTICAST || { stamp "ABORT: lo multicast is OFF (sudo ip link set dev lo multicast on)"; exit 2; }
grep -q "^0,2,4,6,8,10,12-19$" /sys/devices/system/cpu/online || stamp "WARNING: online cpus = $(cat /sys/devices/system/cpu/online) (expected split layout 0,2,4,6,8,10,12-19)"
scripts/host_perf_mode.sh status

# --- 1. Isaac ROS ---
ISAAC_DEST=$HOME/fish_traces/overhead_isaac_split_v6
stamp "Isaac sweep → $ISAAC_DEST"
DEST_BASE=$ISAAC_DEST REPS=3 MODES="base lttng nsys" SMOKE_TIMEOUT=1200 \
  bash scripts/overhead_sweep_v4.sh apriltag bi3d bi3d_freespace dnn_image_encoder dope ess image_proc nvblox segformer stereo_image_proc tensor_rt unet visual_slam
rc=$?; stamp "Isaac rc=$rc"
[ -d "$ISAAC_DEST/apriltag" ] || { stamp "ABORT: Isaac sweep produced nothing (rc=$rc) — not starting Autoware"; exit 3; }
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"

# --- 2. Autoware ---
stamp "Autoware 3x3 (rate 0.5)"
IMG=autoware-dev-trt-a1000-fishwait10:latest REPS=3 bash scripts/autoware_runs/run_overhead_modes.sh
stamp "Autoware rc=$?"
scripts/host_perf_mode.sh status | grep -E "throttle|TCPU"
stamp "DONE"
